// Story of the day: a realistic short story generated by Claude (or an offline template), read once,
// then questions about concrete facts after a delay. Level = number of facts / story length.
import { el, render, sleep } from '../ui.js';
import { makeRng, newSeed } from '../rng.js';
import { fallbackStory } from '../content.js';
import { store } from '../storage.js';
import { aiAvailable, genStory, prefetch } from '../ai.js';

export const meta = { id: 'story', title: 'Історія дня', icon: '📖', desc: 'Реалістична історія з іменами, часом, місцями. Потім запитання. Кожна нова.', defLevel: 1 };

export async function start(done) {
  const level = store.getLevel(meta.id, meta.defLevel);
  const seed = newSeed(); const rng = makeRng(seed);
  render('Історія дня', el('div', { class: 'card center' }, el('span', { class: 'spin' }), ' Пишемо історію…', el('p', { class: 'muted small' }, 'З AI це займає 10-30 секунд')));
  let story = store.cacheTake('story', s => (s.questions?.length || 0) >= 4 + Math.min(level, 4)), source = story ? 'AI (кеш)' : 'офлайн';
  if (!story && aiAvailable()) { try { story = await genStory(level, seed); source = 'AI'; } catch (e) { console.warn(e); } }
  if (!story) story = fallbackStory(rng);
  prefetch('story', level, seed + 3);

  const words = story.text.split(/\s+/).length;
  const readMs = Math.max(20000, words * 450);
  await new Promise(resolve => {
    const bar = el('div', { class: 'progress' }, el('div', { style: `width:100%;transition:width ${readMs}ms linear` }));
    const t = setTimeout(resolve, readMs);
    render(story.title || 'Історія', el('p', { class: 'muted' }, `Прочитайте уважно один раз. Джерело: ${source}`),
      el('div', { class: 'story' }, story.text), bar,
      el('button', { class: 'btn block', style: 'margin-top:12px', onclick: () => { clearTimeout(t); resolve(); } }, 'Я прочитав(ла)'));
    requestAnimationFrame(() => { bar.firstChild.style.width = '0%'; });
  });

  // Delay with a simple distraction
  const delayMs = 8000 + level * 3000;
  render('Пауза', el('div', { class: 'card center' }, el('h2', {}, 'Назвіть подумки 5 предметів у кімнаті'), el('p', { class: 'muted' }, `Запитання за ${Math.round(delayMs / 1000)} с`)));
  await sleep(delayMs);

  let correct = 0;
  const qs = rng.shuffle(story.questions);
  for (let i = 0; i < qs.length; i++) {
    const q = qs[i];
    const opts = rng.shuffle([...new Set([q.a, ...q.opts])]).slice(0, 4);
    if (!opts.includes(q.a)) opts[0] = q.a;
    const ok = await new Promise(resolve => {
      const fb = el('div', { class: 'feedback' });
      const choices = el('div', { class: 'choices' });
      opts.forEach(o => {
        const c = el('div', { class: 'choice' }, o);
        c.onclick = () => {
          choices.querySelectorAll('.choice').forEach(x => { x.onclick = null; if (x.textContent === q.a) x.classList.add('ok'); });
          const okk = o === q.a; if (!okk) c.classList.add('bad');
          fb.textContent = okk ? 'Так ✓' : `Ні. Правильно: ${q.a}`; fb.className = 'feedback ' + (okk ? 'ok' : 'bad');
          setTimeout(() => resolve(okk), okk ? 700 : 1700);
        };
        choices.append(c);
      });
      render(`Запитання ${i + 1} з ${qs.length}`, el('h2', {}, q.q), choices, fb);
    });
    if (ok) correct++;
  }
  // Schedule one spaced question for tomorrow-ish
  const sq = rng.pick(story.questions);
  store.addSpaced({ game: meta.id, interval: 60 * 60e3, due: Date.now() + 60 * 60e3, question: `З історії «${story.title}»: ${sq.q}`, answer: [sq.a], options: [...new Set([sq.a, ...sq.opts])].slice(0, 4) });
  done({ game: meta.id, level, accuracy: correct / qs.length, score: correct, seed, details: `Правильно ${correct} з ${qs.length} · ${source}`, max: 6 });
}
